package com.tripmateai.service.impl; import com.tripmateai.dto.request.booking.*; import com.tripmateai.dto.response.booking.BookingResponse; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.BookingMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.BookingService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class BookingServiceImpl implements BookingService {private final TripRepository trips;private final BookingRepository bookings;private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,user()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not own this trip"):new ResourceNotFoundException("Trip not found"));} private Booking booking(Long t,Long id){return bookings.findByIdAndTrip(id,trip(t)).orElseThrow(()->new ResourceNotFoundException("Booking not found"));} private void dates(java.time.LocalDateTime s,java.time.LocalDateTime e){if(s!=null&&e!=null&&e.isBefore(s))throw new BadRequestException("Booking end time cannot be before start time");} private void set(Booking b,Object r){if(r instanceof CreateBookingRequest x){dates(x.startAt(),x.endAt());b.setType(x.type());b.setStatus(x.status());b.setProvider(x.provider());b.setBookingReference(x.bookingReference());b.setStartAt(x.startAt());b.setEndAt(x.endAt());b.setAmount(x.amount());b.setCurrency(x.currency()==null?"INR":x.currency());b.setDocumentUrl(x.documentUrl());}else {var x=(UpdateBookingRequest)r;dates(x.startAt(),x.endAt());b.setType(x.type());b.setStatus(x.status());b.setProvider(x.provider());b.setBookingReference(x.bookingReference());b.setStartAt(x.startAt());b.setEndAt(x.endAt());b.setAmount(x.amount());b.setCurrency(x.currency()==null?"INR":x.currency());b.setDocumentUrl(x.documentUrl());}} public BookingResponse create(Long id,CreateBookingRequest r){var b=new Booking();b.setTrip(trip(id));b.setUser(user());set(b,r);return BookingMapper.toResponse(bookings.save(b));} @Transactional(readOnly=true) public List<BookingResponse> list(Long id){return bookings.findByTripOrderByStartAtAsc(trip(id)).stream().map(BookingMapper::toResponse).toList();} @Transactional(readOnly=true) public BookingResponse get(Long t,Long id){return BookingMapper.toResponse(booking(t,id));} public BookingResponse update(Long t,Long id,UpdateBookingRequest r){var b=booking(t,id);set(b,r);return BookingMapper.toResponse(bookings.save(b));} public void delete(Long t,Long id){bookings.delete(booking(t,id));}}
